def run(*args: str) -> str:
    cp = subprocess.run(
        args,
        cwd=ROOT,
        text=True,
        encoding="utf-8",
        errors="replace",
        capture_output=True,
    )
    if cp.returncode != 0:
        raise RuntimeError(
            cp.stderr.strip()
            or cp.stdout.strip()
            or f"command failed: {args}"
        )
    return cp.stdout.strip()


def replace_exact(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(
            f"Anchor mismatch for {label}: expected 1, got {count}"
        )
    return text.replace(old, new, 1)


def replace_between(
    text: str,
    start: str,
    end: str,
    replacement: str,
    label: str,
) -> str:
    start_count = text.count(start)
    end_count = text.count(end)
    if start_count != 1 or end_count != 1:
        raise RuntimeError(
            f"Boundary mismatch for {label}: "
            f"start={start_count} end={end_count}"
        )
    left = text.index(start)
    right = text.index(end, left)
    if right <= left:
        raise RuntimeError(f"Invalid boundaries for {label}")
    return text[:left] + replacement + text[right:]


def allowed_untracked(line: str) -> bool:
    return (
        line.startswith("?? stage6h2a_")
        or line.startswith("?? gate_stage6h2a_")
    )


def validate_baseline() -> dict[str, str]:
    head = run("git", "rev-parse", "HEAD")
    origin = run("git", "rev-parse", "origin/main")
    if head != EXPECTED_HEAD or origin != EXPECTED_HEAD:
        raise RuntimeError(
            "Stage 6H.2A baseline mismatch: "
            f"HEAD={head} origin/main={origin} expected={EXPECTED_HEAD}"
        )

    status = run("git", "status", "--porcelain")
    unexpected = [
        line
        for line in status.splitlines()
        if line and not allowed_untracked(line)
    ]
    if unexpected:
        raise RuntimeError(
            "Working tree has unrelated changes; refusing patch:\n"
            + "\n".join(unexpected)
        )

    contents: dict[str, str] = {}
    for rel, expected_sha in EXPECTED_BLOBS.items():
        path = ROOT / rel
        if not path.is_file():
            raise RuntimeError(f"Missing baseline file: {rel}")
        actual_sha = run("git", "hash-object", rel)
        if actual_sha != expected_sha:
            raise RuntimeError(
                f"Baseline blob mismatch for {rel}: "
                f"expected={expected_sha} actual={actual_sha}"
            )
        contents[rel] = path.read_text(encoding="utf-8")

    for rel in NEW_FILES:
        if (ROOT / rel).exists():
            raise RuntimeError(
                f"Refusing to overwrite existing Stage 6H.2A file: {rel}"
            )
    return contents


def render(contents: dict[str, str]) -> dict[str, str]:
    rendered = dict(contents)
    rendered.update(FULL_REPLACEMENTS)

    for rel, operations in REPLACE_OPS.items():
        text = rendered[rel]
        for old, new, label in operations:
            text = replace_exact(text, old, new, label)
        rendered[rel] = text

    for rel, operations in BETWEEN_OPS.items():
        text = rendered[rel]
        for start, end, replacement, label in operations:
            text = replace_between(
                text,
                start,
                end,
                replacement,
                label,
            )
        rendered[rel] = text
    return rendered


def validate_rendered(rendered: dict[str, str]) -> None:
    all_files = dict(rendered)
    all_files.update(NEW_FILES)
    for rel, text in all_files.items():
        if rel.endswith(".py"):
            compile(text, rel, "exec")

    models = rendered["wa_backend/domains/offers/models.py"]
    schemas = rendered["wa_backend/domains/offers/schemas.py"]
    validation = rendered["wa_backend/domains/offers/validation.py"]
    contracts = rendered["wa_backend/domains/offers/contracts.py"]
    engine = rendered["wa_backend/domains/offers/engine.py"]
    eligibility = rendered["wa_backend/domains/offers/eligibility.py"]
    publishing = rendered["wa_backend/domains/offers/publishing.py"]
    preview = rendered["wa_backend/domains/offers/service.py"]
    sale_calc = rendered["wa_backend/domains/sales_calculation/service.py"]
    evidence = rendered["wa_backend/domains/sales_evidence/service.py"]
    migration = NEW_FILES[
        "wa_backend/alembic/versions/"
        "c3f8a1d6e2b4_stage6h2a_mixed_uom_flexible_rewards.py"
    ]

    required = [
        ("uom_id = Column(Integer, nullable=True)" in models, "scope UOM model"),
        ("quantity_per_application = Column(Numeric(20, 6), nullable=True)" in models, "reward quantity model"),
        ("class PreviewComponent" in schemas and "components: list[PreviewComponent]" in schemas, "mixed-UOM preview contract"),
        ("OFFER_REWARD_QUANTITY_REQUIRED" in validation, "multi-reward validation"),
        ("class BasketPriceComponent" in contracts and "price_components:" in contracts, "price component contract"),
        ("ComponentKey = tuple[int, int]" in contracts, "component-level offer key"),
        ("RequestedAdjustment" in engine and "uom_id" in engine, "component-level offer engine"),
        ("OfferProductRef(" in eligibility and "uom_id=int(" in eligibility, "resolver UOM evidence"),
        ("load_variant_uom_authorities" in publishing, "publish-time UOM authority"),
        ("tier[" in publishing and "validate_step=True" in publishing, "publish-time typed quantity/UOM validation"),
        ("component_base_quantities" in preview and "price_components" in preview, "mixed-UOM preview service"),
        ("reward_pairs" in sale_calc and "BasketPriceComponent(" in sale_calc, "live reward UOM price authority"),
        ('"uom_id": row.uom_id' in evidence, "reward UOM evidence"),
        ("_disable_rls_for_admin_migration()" in migration, "RLS-safe empty-data assertion"),
        ("_assert_offer_tables_empty()" in migration, "clean-cut migration guard"),
        ("sa.Column(\"uom_id\", sa.Integer(), nullable=False)" in migration, "reward UOM not-null migration"),
    ]
    failures = [label for ok, label in required if not ok]
    if failures:
        raise RuntimeError(
            "Rendered Stage 6H.2A invariant failure: "
            + ", ".join(failures)
        )

    forbidden = (
        "configuration_schema_version",
        "LegacyBuyXGetYPayload",
        "LegacyFreeGoodsPayload",
        "LegacyBundlePayload",
    )
    joined_offer_runtime = "\n".join(
        rendered[rel]
        for rel in (
            "wa_backend/domains/offers/schemas.py",
            "wa_backend/domains/offers/validation.py",
            "wa_backend/domains/offers/publishing.py",
            "wa_backend/domains/offers/eligibility.py",
            "wa_backend/domains/offers/contracts.py",
            "wa_backend/domains/offers/engine.py",
            "wa_backend/domains/offers/service.py",
        )
    )
    found = [token for token in forbidden if token in joined_offer_runtime]
    if found:
        raise RuntimeError(
            "Clean-cut rule violated by runtime token(s): "
            + ", ".join(found)
        )


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()

    contents = validate_baseline()
    rendered = render(contents)
    validate_rendered(rendered)

    print("STAGE6H2A_PATCH_CHECK=PASS")
    print(f"HEAD={EXPECTED_HEAD}")
    print("ARCHITECTURE=CLEAN_CUT")
    print("MIXED_UOM=COMPONENT_LEVEL")
    print("MULTI_REWARD=ENABLED")
    print("HISTORY_REWRITE=FAIL_CLOSED")
    print("LIVE_MIXED_UOM_SALE_CUTOVER=DEFERRED_TO_6H2B")
    if args.check:
        return 0

    changed = set(FULL_REPLACEMENTS)
    changed.update(REPLACE_OPS)
    changed.update(BETWEEN_OPS)

    for rel in sorted(changed):
        path = ROOT / rel
        path.write_text(
            rendered[rel],
            encoding="utf-8",
            newline="\n",
        )

    for rel, text in NEW_FILES.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            text,
            encoding="utf-8",
            newline="\n",
        )

    run("git", "diff", "--check")
    print("STAGE6H2A_PATCH_APPLIED=PASS")
    print("NEXT=python .\\gate_stage6h2a_mixed_uom_flexible_rewards.py")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
